(6131051, 903436, 88850, '<td valign="top">This is amazing!  Love the glow.</td>', 'This is amazing!  Love the glow.', '2010-08-16 01:12:40.000000', NULL, 1),
(6131059, 903569, 69325, '<td valign="top">well shot, tho the composition seems strange to me, i simply can''t fathom wanting to have kiwi and eggplant at the same time</td>', 'well shot, tho the composition seems strange to me, i simply can''t fathom wanting to have kiwi and eggplant at the same time', '2010-08-16 01:15:35.000000', NULL, 1),
(6131062, 903176, 86447, '<td valign="top">Essence of Techo.  (compliment)<br/> <br/>Congrats!  (not voting)</td>', 'Essence of Techo.  (compliment) Congrats!  (not voting)', '2010-08-16 01:16:07.000000', NULL, 1),
(6131064, 902689, 39429, '<td valign="top">I''m sorry.  A still life is arranged objectes.</td>', 'I''m sorry.  A still life is arranged objectes.', '2010-08-16 01:16:12.000000', NULL, 1),
(6131071, 903117, 69325, '<td valign="top">i like the idea, may not have been an option but i think some older scissors would have given it a better feel. i love the light in this</td>', 'i like the idea, may not have been an option but i think some older scissors would have given it a better feel. i love the light in this', '2010-08-16 01:17:05.000000', NULL, 1),
(6131076, 903747, 88850, '<td valign="top">Interesting and fun.  The lighting is wonderful.</td>', 'Interesting and fun.  The lighting is wonderful.', '2010-08-16 01:17:54.000000', NULL, 1),
(6131077, 903755, 69325, '<td valign="top">ouch, harsh lighting and alot of out of focus areas, which can be good but not in this case. keep working at it!</td>', 'ouch, harsh lighting and alot of out of focus areas, which can be good but not in this case. keep working at it!', '2010-08-16 01:17:59.000000', NULL, 1),
(6131080, 903747, 69325, '<td valign="top">interesting find, i don''t see alot of viewers relating to it however</td>', 'interesting find, i don''t see alot of viewers relating to it however', '2010-08-16 01:18:34.000000', NULL, 1),
(6131085, 902736, 69325, '<td valign="top">lovely comp. and processing, a classic example. nice how you grain without looking like noise just for the sake of it. great job!</td>', 'lovely comp. and processing, a classic example. nice how you grain without looking like noise just for the sake of it. great job!', '2010-08-16 01:19:35.000000', NULL, 1),
(6131089, 903676, 83313, '<td valign="top">Unless the dragonfly is stuffed and mounted, I can''t quite stretch my definition of still life to include one. Pretty good shot, however.</td>', 'Unless the dragonfly is stuffed and mounted, I can''t quite stretch my definition of still life to include one. Pretty good shot, however.', '2010-08-16 01:20:23.000000', NULL, 1),
(6131091, 903465, 69325, '<td valign="top">strange and beautiful! lovely!</td>', 'strange and beautiful! lovely!', '2010-08-16 01:21:26.000000', NULL, 1),
(6131092, 903471, 83313, '<td valign="top">His fly is open.</td>', 'His fly is open.', '2010-08-16 01:21:27.000000', NULL, 1),
(6131093, 903176, 83313, '<td valign="top">Seen this concept somewhere else before. Pretty cool effect and nice work with the lighting.</td>', 'Seen this concept somewhere else before. Pretty cool effect and nice work with the lighting.', '2010-08-16 01:22:18.000000', NULL, 1),
(6131098, 903043, 83313, '<td valign="top">Tinkerer''s heaven!</td>', 'Tinkerer''s heaven!', '2010-08-16 01:23:45.000000', NULL, 1),
(6131103, 902689, 83313, '<td valign="top">How is this a still life? Sorry, but I can''t quite stretch my definition of a still life to include a Ferris wheel. I do like the shot, however.</td>', 'How is this a still life? Sorry, but I can''t quite stretch my definition of a still life to include a Ferris wheel. I do like the shot, however.', '2010-08-16 01:25:27.000000', NULL, 1),
(6131104, 903486, 117534, '<td valign="top">Ansel Adams would be proud of you...</td>', 'Ansel Adams would be proud of you...', '2010-08-16 01:25:29.000000', NULL, 1),
