(6131116, 903398, 69325, '<td valign="top">i miss the smell of vinyl</td>', 'i miss the smell of vinyl', '2010-08-16 01:27:58.000000', NULL, 1),
(6131119, 903213, 83313, '<td valign="top">Excellent pic of a DPC cliche subject.</td>', 'Excellent pic of a DPC cliche subject.', '2010-08-16 01:28:26.000000', NULL, 1),
