(6131434, 903593, 43774, '<td valign="top">Nice setup, you might want to clean the mirror more next time. I like the play of light on the vase.</td>', 'Nice setup, you might want to clean the mirror more next time. I like the play of light on the vase.', '2010-08-16 10:12:59.000000', NULL, 1),
(6131435, 903703, 43774, '<td valign="top">Perhaps a bit overexposed - I think there is milk in the glass but it''s hard to tell because it''s so bright. Cute setup though.</td>', 'Perhaps a bit overexposed - I think there is milk in the glass but it''s hard to tell because it''s so bright. Cute setup though.', '2010-08-16 10:14:06.000000', NULL, 1),
(6131436, 903562, 43774, '<td valign="top">Not fond of the haloing around the trees.....way overprocessed to me.</td>', 'Not fond of the haloing around the trees.....way overprocessed to me.', '2010-08-16 10:14:36.000000', NULL, 1),
(6131438, 903227, 43774, '<td valign="top">That''s cool.</td>', 'That''s cool.', '2010-08-16 10:16:11.000000', NULL, 1),
(6131439, 903227, 118396, '<td valign="top">Very well done - my favorite of this challenge!</td>', 'Very well done - my favorite of this challenge!', '2010-08-16 10:16:30.000000', NULL, 1),
