(6131449, 903676, 103150, '<td valign="top">I''m not sure this counts as "still life". On top of that, it isn''t very interesting.</td>', 'I''m not sure this counts as "still life". On top of that, it isn''t very interesting.', '2010-08-16 10:21:04.000000', NULL, 1),
(6131450, 902540, 43774, '<td valign="top">I think this would be just as good or better without the streaks of light in the background. Your lighting on the statue is very good.</td>', 'I think this would be just as good or better without the streaks of light in the background. Your lighting on the statue is very good.', '2010-08-16 10:22:13.000000', NULL, 1),
(6131451, 903393, 43774, '<td valign="top">Clever!</td>', 'Clever!', '2010-08-16 10:22:36.000000', NULL, 1),
(6131452, 903703, 118396, '<td valign="top">Oreos are always a winner.  I wish I could see the contents of the glass better, but I still really like this.</td>', 'Oreos are always a winner.  I wish I could see the contents of the glass better, but I still really like this.', '2010-08-16 10:22:40.000000', NULL, 1),
