INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6131851, 903680, 96751, '<td valign="top">I like the composition, but not the processing.  It''s a bit heavy for such delicate subjects.</td>', 'I like the composition, but not the processing.  It''s a bit heavy for such delicate subjects.', '2010-08-16 15:49:44.000000', NULL, 1),
(6131852, 903228, 96751, '<td valign="top">Very interesting abstract.  Love those shadows.</td>', 'Very interesting abstract.  Love those shadows.', '2010-08-16 15:50:03.000000', NULL, 1),
(6131855, 903534, 98339, '<td valign="top">this seems quite "close", it is in super clear focus, but it is also dead centered...(that is just something that bugs me...don''t take it personal)</td>', 'this seems quite "close", it is in super clear focus, but it is also dead centered...(that is just something that bugs me...don''t take it personal)', '2010-08-16 15:50:44.000000', NULL, 1),
(6131856, 903176, 62895, '<td valign="top">Nice clean image. The lighting and focus are both great. I can''t help but think it needs something more though, I''m not sure what.</td>', 'Nice clean image. The lighting and focus are both great. I can''t help but think it needs something more though, I''m not sure what.', '2010-08-16 15:51:26.000000', NULL, 1),
(6131857, 903465, 104009, '<td valign="top">oh now this is different!  I like the leading lines and the away-facing sunflower, very well done and original. the soft focus on the flame looks a little wrong 8</td>', 'oh now this is different!  I like the leading lines and the away-facing sunflower, very well done and original. the soft focus on the flame looks a little wrong 8', '2010-08-16 15:51:40.000000', NULL, 1),
(6131858, 903623, 104009, '<td valign="top">a week too early for the rust challenge!  nice choice of a different subject and like the setup a lot 8</td>', 'a week too early for the rust challenge!  nice choice of a different subject and like the setup a lot 8', '2010-08-16 15:52:13.000000', NULL, 1),
(6131859, 903723, 98339, '<td valign="top">boy the computer did something very weird there...so you might get two comments from me...this is the real deal...<br/> <br/>I like your conversion to B&amp;W...nice rich tones...BUT I don''t get how this is considered to be a still life?  I''m really trying to broaden my horizons...but this is more landscape than still life...sorry</td>', 'boy the computer did something very weird there...so you might get two comments from me...this is the real deal... I like your conversion to B&W...nice rich tones...BUT I don''t get how this is considered to be a still life?  I''m really trying to broaden my horizons...but this is more landscape than still life...sorry', '2010-08-16 15:52:21.000000', NULL, 1),
(6131860, 903254, 96751, '<td valign="top">I really like the coffee grinder and the soft focus, but find the tablecloth distracting.</td>', 'I really like the coffee grinder and the soft focus, but find the tablecloth distracting.', '2010-08-16 15:52:50.000000', NULL, 1),
(6131861, 903598, 96751, '<td valign="top">Very painterly.</td>', 'Very painterly.', '2010-08-16 15:53:06.000000', NULL, 1),
(6131862, 903117, 62895, '<td valign="top">You''ve used mundane elements and everyday lighting and combined them into a really nice image. Well done. The string works really well in B&amp;W.</td>', 'You''ve used mundane elements and everyday lighting and combined them into a really nice image. Well done. The string works really well in B&W.', '2010-08-16 15:53:39.000000', NULL, 1),
(6131863, 903670, 98339, '<td valign="top">couple of things...to me this seems to be just to blooming close...I think you would have had a better effect if you had "stepped back" just a bit...and the other thing is the graininess...a noise reducing software would really have helped this alot</td>', 'couple of things...to me this seems to be just to blooming close...I think you would have had a better effect if you had "stepped back" just a bit...and the other thing is the graininess...a noise reducing software would really have helped this alot', '2010-08-16 15:53:41.000000', NULL, 1),
(6131864, 903519, 96751, '<td valign="top">I think the heavy contrast makes this more of an abstract, but it''s very interesting compositionally.</td>', 'I think the heavy contrast makes this more of an abstract, but it''s very interesting compositionally.', '2010-08-16 15:53:49.000000', NULL, 1),
(6131865, 903562, 98339, '<td valign="top">ok, it''s still, but I don''t like the weird glow around the wood...it takes away from the feature</td>', 'ok, it''s still, but I don''t like the weird glow around the wood...it takes away from the feature', '2010-08-16 15:54:27.000000', NULL, 1),
(6131866, 903436, 62895, '<td valign="top">So moody and dark, I really like the processing and overall effect this photo has. Rather mysterious. (no vote)</td>', 'So moody and dark, I really like the processing and overall effect this photo has. Rather mysterious. (no vote)', '2010-08-16 15:54:27.000000', NULL, 1),
(6131867, 903340, 96751, '<td valign="top">Breathtaking.  A fave (I''m a sucker for dandelions), although I don''t think this qualifies as a still life.</td>', 'Breathtaking.  A fave (I''m a sucker for dandelions), although I don''t think this qualifies as a still life.', '2010-08-16 15:54:38.000000', NULL, 1),
