(6132218, 903465, 108069, '<td valign="top">Beautiful image.</td>', 'Beautiful image.', '2010-08-16 20:09:20.000000', NULL, 1),
(6132220, 903598, 108069, '<td valign="top">Very nice. Great composition and perfect processing. Well done.</td>', 'Very nice. Great composition and perfect processing. Well done.', '2010-08-16 20:11:17.000000', NULL, 1),
(6132225, 903103, 108069, '<td valign="top">I really like the arrangement and textures, but I think I would have tried a deeper depth of field. Or set the jars back a bit so they weren''t on the cusp of being in focus. No matter, I still like it a lot.</td>', 'I really like the arrangement and textures, but I think I would have tried a deeper depth of field. Or set the jars back a bit so they weren''t on the cusp of being in focus. No matter, I still like it a lot.', '2010-08-16 20:13:18.000000', NULL, 1),
(6132226, 903176, 108069, '<td valign="top">Cool shot. Great texture.</td>', 'Cool shot. Great texture.', '2010-08-16 20:13:56.000000', NULL, 1),
(6132228, 902926, 116354, '<td valign="top">This is a nice composition, but I think there is a tad too much processing going on - a simpler processed image would have looked more appealing.</td>', 'This is a nice composition, but I think there is a tad too much processing going on - a simpler processed image would have looked more appealing.', '2010-08-16 20:16:00.000000', NULL, 1),
(6132231, 903118, 116354, '<td valign="top">Nice composition, but it would have benefited from a larger DOF. Also, the wine glass is almost bleeding into background.</td>', 'Nice composition, but it would have benefited from a larger DOF. Also, the wine glass is almost bleeding into background.', '2010-08-16 20:19:44.000000', NULL, 1),
(6132235, 903533, 116354, '<td valign="top">I find the composition a bit distracting. I would have preferred either more central, or more to one of the sides. Also, vignette looks a bit fake here :-)</td>', 'I find the composition a bit distracting. I would have preferred either more central, or more to one of the sides. Also, vignette looks a bit fake here :-)', '2010-08-16 20:21:44.000000', NULL, 1),
(6132236, 903176, 90495, '<td valign="top">This is cool as heck. So simple and yet so abstract.</td>', 'This is cool as heck. So simple and yet so abstract.', '2010-08-16 20:22:11.000000', NULL, 1),
(6132239, 903398, 116354, '<td valign="top">Very original idea - big plus, especially in this challenge!</td>', 'Very original idea - big plus, especially in this challenge!', '2010-08-16 20:29:17.000000', NULL, 1),
(6132240, 903598, 116354, '<td valign="top">I like the contrast and lighting - good use of black and white :-) I wonder if something less empty than a jar could have been used instead.</td>', 'I like the contrast and lighting - good use of black and white :-) I wonder if something less empty than a jar could have been used instead.', '2010-08-16 20:31:37.000000', NULL, 1),
(6132241, 903227, 90495, '<td valign="top">Frankenpear. Very very cool. Well photographed too with the shallow dof being utilized to enhance the frankenpear in the background. Keep your original file because this should win a ribbon and I don''t want to see it get DQed. :)</td>', 'Frankenpear. Very very cool. Well photographed too with the shallow dof being utilized to enhance the frankenpear in the background. Keep your original file because this should win a ribbon and I don''t want to see it get DQed. :)', '2010-08-16 20:32:33.000000', NULL, 1),
(6132243, 903309, 90495, '<td valign="top">Great lighting.</td>', 'Great lighting.', '2010-08-16 20:34:28.000000', NULL, 1),
(6132245, 903426, 90495, '<td valign="top">This looks under exposed. I don''t usually make this kind of comment but the fact the wine bottle is well exposed gives me the impression the rest of the photo was not lit enough.</td>', 'This looks under exposed. I don''t usually make this kind of comment but the fact the wine bottle is well exposed gives me the impression the rest of the photo was not lit enough.', '2010-08-16 20:40:53.000000', NULL, 1),
(6132246, 903789, 116354, '<td valign="top">Brilliant execution! Seriously, with the abundance of glass shots here and elsewhere, they just have became cliché... This one is top notch though. Congrats!</td>', 'Brilliant execution! Seriously, with the abundance of glass shots here and elsewhere, they just have became cliché... This one is top notch though. Congrats!', '2010-08-16 20:42:23.000000', NULL, 1),
(6132253, 903118, 10785, '<td valign="top">A nice arrangement. You have all the elements of a great classic still Life. I can''t help but notice the photo is out of focus.</td>', 'A nice arrangement. You have all the elements of a great classic still Life. I can''t help but notice the photo is out of focus.', '2010-08-16 20:48:32.000000', NULL, 1),
